(function(){
const KEY='senxi-toolbox-v1';let state={favorites:[],recent:[]},catalog=[],loading=null,memory=false,queued=false;
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
function read(){try{const d=JSON.parse(localStorage.getItem(KEY)||'{}');state.favorites=[...new Set((Array.isArray(d.favorites)?d.favorites:[]).filter(x=>typeof x==='string'&&x.length<180))].slice(0,100);state.recent=(Array.isArray(d.recent)?d.recent:[]).filter(x=>x&&typeof x.id==='string'&&x.id.length<180&&Number.isFinite(x.at)).slice(0,12)}catch(e){memory=true}}read();
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){memory=true;notice('浏览器未允许保存，收藏仅在本次打开期间保留',true)}counts()}
function remember(id){if(!id||id==='tool:home'||id.startsWith('collection:'))return;state.recent=[{id,at:Date.now()},...state.recent.filter(x=>x.id!==id)].slice(0,12);persist()}
function toggle(id){if(state.favorites.includes(id))state.favorites=state.favorites.filter(x=>x!==id);else{if(state.favorites.length>=100)return notice('最多收藏100项，请先移除部分收藏');state.favorites.push(id)}persist();decorate();if(page==='toolbox')collection(document.body.dataset.collection);if(dialog.open)results()}
function star(id,label){const b=el('button',undefined,'tb-star');b.type='button';b.dataset.favorite=id;b.dataset.label=label;const saved=state.favorites.includes(id);b.textContent=saved?'★ 已收藏':'☆ 收藏';b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',(saved?'取消收藏：':'收藏：')+label);b.onclick=()=>toggle(id);return b}
function counts(){document.querySelectorAll('[data-tb-count]').forEach(e=>{const text=e.dataset.tbCount==='favorites'?'我的收藏 '+state.favorites.length:'最近使用 '+state.recent.length;if(e.textContent!==text)e.textContent=text})}
async function source(endpoint,file){if(!staticPreview){try{return(await api(endpoint)).items.filter(i=>i.published)}catch(e){}}const r=await fetch(file);if(!r.ok)throw Error('资料读取失败，请稍后重试');return(await r.json()).items.filter(i=>i.published)}
async function load(){if(loading)return loading;loading=(async()=>{const [lineups,crosshairs,agentData]=await Promise.all([source('lineups','lineups-seed.json'),source('crosshairs','crosshairs-seed.json'),fetch('agents.json').then(r=>{if(!r.ok)throw Error('英雄资料读取失败');return r.json()})]);const agents=agentData.agents;const entries=[['maps','地图资料库'],['lineups','道具点位'],['crosshairs','准星库'],['generator','准星生成器'],['guide','准星设置教程']].map(([id,title])=>({id:'tool:'+id,title,type:'工具',description:'森希战术工具箱'}));for(const m of maps){entries.push({id:'map:'+m.uuid,title:name(m),type:'地图',description:m.en?.displayName||'',mapId:m.uuid});m.callouts.forEach((c,i)=>entries.push({id:'point:'+m.uuid+':'+i,title:[c.superRegionName,c.regionName].filter(Boolean).join(' · '),type:'地图点位',description:name(m)+' '+m.en?.displayName,mapId:m.uuid,index:i}))}for(const i of lineups){const m=maps.find(m=>m.uuid===i.mapId),a=agents.find(a=>a.id===i.agentId);entries.push({id:'lineup:'+i.id,title:i.title,type:'道具',description:[m?name(m):'',a?.name,a?.en,i.side,i.ability,i.standing,i.instructions].join(' '),item:i})}for(const i of crosshairs)entries.push({id:'crosshair:'+i.id,title:i.name,type:'准星',description:i.description,item:i});catalog=entries;return catalog})().finally(()=>loading=null);return loading}
async function open(id,hash=true){try{if(!catalog.length)await load();if(hash){const next='#tool='+encodeURIComponent(id);if(location.hash!==next){location.hash=next;return}}if(id==='tool:home'){home();return}if(id.startsWith('collection:')){await load();collection(id.slice(11));return}const item=catalog.find(x=>x.id===id);if(!item){notice('这项内容已下架或不可用，可从收藏中移除',true);return}remember(id);if(item.mapId){query='';current=maps.find(m=>m.uuid===item.mapId);selected=item.index??null;show();requestAnimationFrame(()=>document.querySelector('.pin.selected')?.scrollIntoView({block:'nearest',inline:'nearest'}))}else if(id.startsWith('lineup:')){luMap=item.item.mapId;luAgent=item.item.agentId;luSide='';luQuery='';luSelected=item.item.id;await showLineups()}else if(id.startsWith('crosshair:')){chSearch=item.title;await showCrosshairs('library')}else if(id==='tool:maps'){query='';show()}else if(id==='tool:lineups')await showLineups();else await showCrosshairs(id==='tool:generator'?'generator':id==='tool:guide'?'guide':'library');window.scrollTo({top:0,behavior:'instant'});decorate()}catch(e){notice(e.message,true)}}
const dialog=el('dialog');dialog.id='tb-search-dialog';dialog.setAttribute('aria-label','搜索战术工具箱');dialog.innerHTML='<button type="button" id="tb-close">关闭 ×</button><h2>搜索战术工具箱</h2><p>输入地图、英雄、点位、技能或准星名称</p><input id="tb-query" aria-label="统一搜索" placeholder="例如：Ascent、猎枭、树木、青色"><div id="tb-types" class="toolbar"></div><p id="tb-result-count" role="status"></p><div id="tb-results"></div>';document.body.append(dialog);let filter='全部';const input=dialog.querySelector('#tb-query');input.oninput=results;dialog.querySelector('#tb-close').onclick=()=>dialog.close();for(const type of ['全部','工具','地图','地图点位','道具','准星']){const b=el('button',type);b.type='button';b.onclick=()=>{filter=type;results()};dialog.querySelector('#tb-types').append(b)}
function row(item,unavailableId){const r=el('div',undefined,'tb-result');if(!item){r.append(el('span','内容已下架或不可用'));const remove=el('button','移除收藏');remove.onclick=()=>toggle(unavailableId);r.append(remove);return r}const b=el('button',undefined,'tb-open');b.append(el('small',item.type),el('strong',item.title),el('span',item.description.slice(0,100)));b.onclick=()=>{dialog.close();open(item.id)};r.append(b,star(item.id,item.title));return r}
function results(){const tokens=input.value.normalize('NFKC').trim().toLowerCase().split(/\s+/).filter(Boolean);const items=catalog.filter(i=>(filter==='全部'||i.type===filter)&&tokens.every(t=>(i.title+' '+i.description).normalize('NFKC').toLowerCase().includes(t)));const list=dialog.querySelector('#tb-results');list.replaceChildren();for(const i of items.slice(0,40))list.append(row(i));if(!items.length)list.append(el('p','没有找到匹配内容，试试地图英文名、英雄名或更短的关键词。'));dialog.querySelector('#tb-result-count').textContent=items.length+' 条结果'+(items.length>40?'，显示前40条，请缩小搜索范围':'');dialog.querySelectorAll('#tb-types button').forEach(b=>{b.classList.toggle('active',b.textContent===filter);b.setAttribute('aria-pressed',String(b.textContent===filter))})}
async function search(){dialog.showModal();input.focus();dialog.querySelector('#tb-result-count').textContent='正在读取工具资料…';try{await load();results()}catch(e){dialog.querySelector('#tb-result-count').textContent=e.message}}
function collection(kind){page='toolbox';document.body.dataset.page='toolbox';document.body.dataset.collection=kind;mapObserver?.disconnect();document.title=(kind==='recent'?'最近使用':'我的收藏')+' · 森希Valorant';root.replaceChildren();root.append(el('div','森希Valorant / 战术工具箱','brand-section'),el('h1',kind==='recent'?'继续上次的练习':'我的收藏'),el('p','记录保存在当前浏览器中，无需登录。不同设备与浏览器不会自动同步。'+(memory?'当前浏览器未允许持久保存。':'')));const list=el('div',undefined,'panel tb-saved-list');const ids=kind==='recent'?state.recent.map(x=>x.id):state.favorites;if(!ids.length){list.append(el('h2',kind==='recent'?'还没有使用记录':'还没有收藏'),el('p','打开地图、道具点位或准星条目，点击“收藏”后即可在这里快速找到。'));const b=el('button','浏览地图资料库');b.onclick=()=>open('tool:maps');list.append(b)}for(const id of ids){const item=catalog.find(i=>i.id===id);if(item)list.append(row(item));else if(kind!=='recent')list.append(row(null,id))}root.append(list);if(kind==='recent'&&ids.length){const clear=el('button','清空最近使用');clear.onclick=()=>{state.recent=[];persist();collection('recent')};root.append(clear)}navState()}
const nav=el('nav',undefined,'tb-nav');nav.setAttribute('aria-label','战术工具箱导航');for(const[id,label]of [['tool:home','首页'],['tool:maps','地图'],['tool:lineups','道具点位'],['tool:crosshairs','准星设置'],['collection:favorites','我的收藏'],['collection:recent','最近使用']]){const b=el('button',label);b.type='button';b.dataset.route=id;if(id.startsWith('collection:'))b.dataset.tbCount=id.slice(11);b.onclick=()=>open(id);nav.append(b)}const searchButton=el('button','搜索工具箱 /');searchButton.id='tb-open-search';searchButton.onclick=search;nav.append(searchButton);document.querySelector('header').after(nav);document.querySelector('#home').hidden=true;document.querySelector('#brand-home').onclick=e=>{e.preventDefault();open('tool:home')};
function navState(){nav.querySelectorAll('[data-route]').forEach(b=>{const active=b.dataset.route==='tool:'+page||(page==='crosshairs'&&b.dataset.route==='tool:crosshairs')||(page==='toolbox'&&b.dataset.route==='collection:'+document.body.dataset.collection);b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
let lastContext='';function decorate(){counts();navState();document.querySelectorAll('[data-favorite]').forEach(b=>{const saved=state.favorites.includes(b.dataset.favorite),text=saved?'★ 已收藏':'☆ 收藏';if(b.textContent!==text)b.textContent=text;b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',(saved?'取消收藏：':'收藏：')+(b.dataset.label||''))});if(page==='home'){for(const [selector,id]of [['#enter','tool:maps'],['#enter-lineups','tool:lineups'],['#enter-crosshairs','tool:crosshairs']]){const b=document.querySelector(selector);if(b)b.onclick=()=>open(id)}const hub=document.querySelector('#tool-hub');if(hub&&!document.querySelector('#tb-dashboard')){const bar=el('div',undefined,'tb-dashboard');bar.id='tb-dashboard';const searchBox=el('button','搜索地图、点位、英雄或准星');searchBox.onclick=search;bar.append(searchBox);for(const kind of ['favorites','recent']){const b=el('button');b.dataset.tbCount=kind;b.onclick=()=>open('collection:'+kind);bar.append(b)}hub.prepend(bar);counts()}return}let id,label,parent;if(page==='maps'&&current){id=selected!==null?'point:'+current.uuid+':'+selected:'map:'+current.uuid;label=selected!==null?[current.callouts[selected]?.superRegionName,current.callouts[selected]?.regionName].filter(Boolean).join(' · '):name(current);parent=document.querySelector('#detail')}else if(page==='lineups'&&document.querySelector('.lu-card.active')){const i=luItems.find(i=>i.id===luSelected&&i.published);if(i){id='lineup:'+i.id;label=i.title;parent=document.querySelector('#lu-detail')}}else if(page==='crosshairs'){const cards=[...document.querySelectorAll('.ch-card')];for(const card of cards){const title=card.querySelector('h3')?.textContent,i=chItems.find(i=>i.id===card.dataset.crosshairId&&i.published);if(i&&!card.querySelector('[data-favorite]')){const b=star('crosshair:'+i.id,i.name);card.append(b)}}}if(parent&&id){const old=parent.querySelector('.tb-context');if(old?.dataset.key!==id){old?.remove();const bar=el('div',undefined,'tb-context');bar.dataset.key=id;bar.append(el('span',label),star(id,label));parent.prepend(bar)}if(lastContext!==id){lastContext=id;remember(id)}}}
new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;decorate()})}).observe(root,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
window.addEventListener('hashchange',()=>{const id=new URLSearchParams(location.hash.slice(1)).get('tool');if(id)open(id,false);else if(!location.hash)open('tool:home',false)});window.addEventListener('storage',e=>{if(e.key===KEY){read();decorate();if(page==='toolbox')collection(document.body.dataset.collection)}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,textarea,select,[contenteditable=true]')&&!document.querySelector('dialog[open]')){e.preventDefault();search()}});
window.Toolbox={open,search,load,decorate,remember,getState:()=>structuredClone(state)};decorate();const initial=new URLSearchParams(location.hash.slice(1)).get('tool');if(initial)open(initial,false);
})();
